// CrUX History API レスポンスを日次 timeseries 行に展開
// 各 URL × 各 collection_period (最大28日) で 1 row
// 404 (NOT_FOUND) や JSON 不正は debug 行を 1 行 emit (collection_period = snapshot_date)

const urls = $('BigQuery: Get Top URLs').all();
const now = new Date().toISOString();
const snapshotDate = new Date(Date.now() + 9*60*60*1000).toISOString().substring(0,10);
const rows = [];

// debug 行 builder (raw_payload に エラー詳細を入れる)
const emitDebug = (url, payloadStr, note) => {
  rows.push({
    snapshot_date:           snapshotDate,
    url:                     url,
    form_factor:             'DEBUG_' + (note || 'UNKNOWN'),
    collection_period_start: snapshotDate,
    collection_period_end:   snapshotDate,
    raw_payload:             (payloadStr || '').substring(0, 100000),
    inserted_at:             now
  });
};

const inputs = $input.all();
for (let i = 0; i < inputs.length; i++) {
  const url = urls[i]?.json?.url;
  if (!url) continue;
  const raw = inputs[i].json;
  let bodyStr = null;
  if (raw && typeof raw === 'object' && typeof raw.data === 'string') bodyStr = raw.data;
  else if (typeof raw === 'string') bodyStr = raw;
  else if (raw && typeof raw === 'object') bodyStr = JSON.stringify(raw);
  if (!bodyStr || bodyStr.trim() === '') { emitDebug(url, '<empty body>', 'EMPTY'); continue; }
  let resp;
  try { resp = JSON.parse(bodyStr); } catch (e) { emitDebug(url, bodyStr, 'PARSE_FAIL'); continue; }
  if (resp && resp.error)  { emitDebug(url, bodyStr, 'API_ERR_' + (resp.error.code || 'X')); continue; }
  if (!resp || !resp.record) { emitDebug(url, bodyStr, 'NO_RECORD'); continue; }
  const record = resp.record;
  const periods = record.collectionPeriods || [];
  const metrics = record.metrics || {};

  // metric 名 -> 内部キー
  const lcp  = metrics.largest_contentful_paint;
  const inp  = metrics.interaction_to_next_paint;
  const cls  = metrics.cumulative_layout_shift;
  const fcp  = metrics.first_contentful_paint;
  const ttfb = metrics.experimental_time_to_first_byte;

  // 各 metric の percentilesTimeseries.p75s と histogramTimeseries.densities は配列
  // periods と同じ長さで、indexで対応する
  const pickDensity = (m, idx, name) => {
    if (!m || !m.histogramTimeseries) return null;
    const seriesBin = m.histogramTimeseries.find(b => b.binDescription === name || b.binStart === name);
    return null;
  };

  // CrUX histogramTimeseries: each metric has 3 bins (good / needs-improvement / poor)
  // densities[i] is the density value for period i
  const getBinDensities = (m) => {
    if (!m || !m.histogramTimeseries || !Array.isArray(m.histogramTimeseries) || m.histogramTimeseries.length < 3) return [[], [], []];
    return [
      m.histogramTimeseries[0]?.densities || [],
      m.histogramTimeseries[1]?.densities || [],
      m.histogramTimeseries[2]?.densities || []
    ];
  };
  const getP75 = (m) => {
    if (!m || !m.percentilesTimeseries || !m.percentilesTimeseries.p75s) return [];
    return m.percentilesTimeseries.p75s;
  };

  const lcpBins = getBinDensities(lcp);  // [good[], ni[], poor[]]
  const inpBins = getBinDensities(inp);
  const clsBins = getBinDensities(cls);
  const lcpP75 = getP75(lcp);
  const inpP75 = getP75(inp);
  const clsP75 = getP75(cls);
  const fcpP75 = getP75(fcp);
  const ttfbP75 = getP75(ttfb);

  for (let p = 0; p < periods.length; p++) {
    const period = periods[p];
    const startDate = period.firstDate ? `${period.firstDate.year}-${String(period.firstDate.month).padStart(2,'0')}-${String(period.firstDate.day).padStart(2,'0')}` : null;
    const endDate   = period.lastDate  ? `${period.lastDate.year}-${String(period.lastDate.month).padStart(2,'0')}-${String(period.lastDate.day).padStart(2,'0')}`   : null;
    if (!startDate || !endDate) continue;

    const toNum = v => (v === undefined || v === null || v === '') ? null : Number(v);

    rows.push({
      snapshot_date:           snapshotDate,
      url:                     url,
      form_factor:             'ALL_FORM_FACTORS',
      collection_period_start: startDate,
      collection_period_end:   endDate,
      lcp_p75_ms:              toNum(lcpP75[p]),
      lcp_good_density:        toNum(lcpBins[0][p]),
      lcp_ni_density:          toNum(lcpBins[1][p]),
      lcp_poor_density:        toNum(lcpBins[2][p]),
      inp_p75_ms:              toNum(inpP75[p]),
      inp_good_density:        toNum(inpBins[0][p]),
      inp_ni_density:          toNum(inpBins[1][p]),
      inp_poor_density:        toNum(inpBins[2][p]),
      cls_p75:                 toNum(clsP75[p]),
      cls_good_density:        toNum(clsBins[0][p]),
      cls_ni_density:          toNum(clsBins[1][p]),
      cls_poor_density:        toNum(clsBins[2][p]),
      fcp_p75_ms:              toNum(fcpP75[p]),
      ttfb_p75_ms:              toNum(ttfbP75[p]),
      raw_payload:             JSON.stringify(resp).substring(0, 100000),
      inserted_at:             now
    });
  }
}

return rows.map(json => ({ json }));
